                'MATRIX-JOB os=windows-latest node=18',
                'MATRIX-JOB os=windows-latest node=20')) {
            $script:actText.Contains($leg) | Should -BeTrue -Because "leg '$leg' must run"
        }
    }

    It 'every job reports Job succeeded and none failed' {
